{
    "level": "B1–B2",
    "intro": "У цій темі ти вивчиш, як утворювати пасив з <strong>фразовими дієсловами<\/strong>. Головне правило: <strong>прийменник або частка залишається з дієсловом<\/strong>.",
    "rules": [
        {
            "label": "Активний",
            "color": "emerald",
            "text": "<strong>Subject + phrasal verb + object<\/strong>:",
            "example": "They called off the meeting."
        },
        {
            "label": "Пасивний",
            "color": "blue",
            "text": "<strong>Object + be + V3 + particle\/preposition<\/strong>:",
            "example": "The meeting was called off."
        },
        {
            "label": "Важливо",
            "color": "rose",
            "text": "Частка\/прийменник <strong>не відривається<\/strong> від дієслова:",
            "example": "The baby was looked after. ✅ (не: was looked the baby after ❌)"
        }
    ]
}

{
    "title": "1. Типові фразові дієслова у пасиві",
    "intro": "Найпоширеніші фразові дієслова, що вживаються в пасиві:",
    "items": [
        {
            "label": "look after",
            "title": "доглядати",
            "subtitle": "The children are looked after well."
        },
        {
            "label": "bring up",
            "title": "виховувати",
            "subtitle": "She was brought up by her grandmother."
        },
        {
            "label": "call off",
            "title": "скасувати",
            "subtitle": "The match was called off."
        },
        {
            "label": "put off",
            "title": "відкладати",
            "subtitle": "The meeting was put off until Monday."
        },
        {
            "label": "turn down",
            "title": "відхиляти",
            "subtitle": "His offer was turned down."
        },
        {
            "label": "carry out",
            "title": "виконувати",
            "subtitle": "The experiment was carried out."
        },
        {
            "label": "look into",
            "title": "розслідувати",
            "subtitle": "The matter is being looked into."
        },
        {
            "label": "break into",
            "title": "вламуватися",
            "subtitle": "The house was broken into."
        }
    ]
}

{
    "title": "2. Порівняння Active vs Passive",
    "intro": "Перетворення фразових дієслів з активу в пасив:",
    "rows": [
        {
            "en": "Active: They called off the game.",
            "ua": "Вони скасували гру.",
            "note": "→ Passive: The game was called off."
        },
        {
            "en": "Active: Someone broke into the car.",
            "ua": "Хтось вламався в машину.",
            "note": "→ Passive: The car was broken into."
        },
        {
            "en": "Active: They are looking into the problem.",
            "ua": "Вони розслідують проблему.",
            "note": "→ Passive: The problem is being looked into."
        },
        {
            "en": "Active: Her grandparents brought her up.",
            "ua": "Її виховували бабуся і дідусь.",
            "note": "→ Passive: She was brought up by her grandparents."
        }
    ],
    "warning": "📌 Частка\/прийменник ЗАВЖДИ залишається з дієсловом!"
}

{
    "title": "3. Фразові дієслова у пасиві за категоріями",
    "sections": [
        {
            "label": "Скасування \/ відкладання",
            "color": "rose",
            "description": "call off, put off, cancel:",
            "examples": [
                {
                    "en": "The concert was called off due to rain.",
                    "ua": "Концерт скасували через дощ."
                },
                {
                    "en": "The meeting has been put off.",
                    "ua": "Зустріч відклали."
                },
                {
                    "en": "The flight was put off until tomorrow.",
                    "ua": "Рейс перенесли на завтра."
                }
            ]
        },
        {
            "label": "Виконання \/ здійснення",
            "color": "emerald",
            "description": "carry out, bring about, set up:",
            "examples": [
                {
                    "en": "The research was carried out last year.",
                    "ua": "Дослідження провели минулого року."
                },
                {
                    "en": "Major changes were brought about.",
                    "ua": "Були внесені значні зміни."
                },
                {
                    "en": "A new company was set up.",
                    "ua": "Була створена нова компанія."
                }
            ]
        },
        {
            "label": "Відхилення \/ відмова",
            "color": "blue",
            "description": "turn down, rule out, throw out:",
            "examples": [
                {
                    "en": "Her application was turned down.",
                    "ua": "Її заявку відхилили."
                },
                {
                    "en": "This option cannot be ruled out.",
                    "ua": "Цей варіант не можна виключати."
                },
                {
                    "en": "The proposal was thrown out.",
                    "ua": "Пропозицію відкинули."
                }
            ]
        },
        {
            "label": "Догляд \/ виховання",
            "color": "amber",
            "description": "look after, bring up, take care of:",
            "examples": [
                {
                    "en": "The patient is being looked after.",
                    "ua": "За пацієнтом доглядають."
                },
                {
                    "en": "He was brought up in a small village.",
                    "ua": "Він виріс у маленькому селі."
                },
                {
                    "en": "Everything will be taken care of.",
                    "ua": "Про все подбають."
                }
            ]
        }
    ]
}

{
    "title": "4. Фразові дієслова у пасиві: різні часи",
    "sections": [
        {
            "label": "Present Simple",
            "color": "emerald",
            "description": "<strong>am\/is\/are + V3 + particle<\/strong>:",
            "examples": [
                {
                    "en": "Children are looked after at the nursery.",
                    "ua": "За дітьми доглядають у дитсадку."
                },
                {
                    "en": "Problems are dealt with quickly.",
                    "ua": "Проблеми вирішуються швидко."
                }
            ]
        },
        {
            "label": "Past Simple",
            "color": "blue",
            "description": "<strong>was\/were + V3 + particle<\/strong>:",
            "examples": [
                {
                    "en": "The project was carried out successfully.",
                    "ua": "Проєкт було успішно виконано."
                },
                {
                    "en": "The meeting was called off yesterday.",
                    "ua": "Зустріч скасували вчора."
                }
            ]
        },
        {
            "label": "Present Perfect",
            "color": "amber",
            "description": "<strong>has\/have been + V3 + particle<\/strong>:",
            "examples": [
                {
                    "en": "The event has been put off.",
                    "ua": "Захід відклали."
                },
                {
                    "en": "His idea has been turned down.",
                    "ua": "Його ідею відхилили."
                }
            ]
        },
        {
            "label": "Present Continuous",
            "color": "rose",
            "description": "<strong>am\/is\/are being + V3 + particle<\/strong>:",
            "examples": [
                {
                    "en": "The matter is being looked into.",
                    "ua": "Справу розслідують."
                },
                {
                    "en": "New measures are being brought in.",
                    "ua": "Впроваджуються нові заходи."
                }
            ]
        }
    ]
}

{
    "title": "5. Дієслова з прийменниками у пасиві",
    "intro": "Дієслова з фіксованими прийменниками також утворюють пасив:",
    "items": [
        {
            "label": "laugh at",
            "title": "сміятися з",
            "subtitle": "He hates being laughed at."
        },
        {
            "label": "look at",
            "title": "дивитися на",
            "subtitle": "The painting is being looked at."
        },
        {
            "label": "speak to",
            "title": "говорити з",
            "subtitle": "I don't like being spoken to like that."
        },
        {
            "label": "refer to",
            "title": "посилатися на",
            "subtitle": "This book is often referred to."
        },
        {
            "label": "rely on",
            "title": "покладатися на",
            "subtitle": "He can be relied on."
        },
        {
            "label": "deal with",
            "title": "мати справу з",
            "subtitle": "The problem is being dealt with."
        }
    ]
}

{
    "title": "6. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Відривання частки від дієслова.",
            "wrong": "The baby was looked well after.",
            "right": "✅ The baby was looked after well."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Пропуск частки\/прийменника.",
            "wrong": "The meeting was called.",
            "right": "✅ The meeting was called off."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Неправильний прийменник.",
            "wrong": "He was laughed on by everyone.",
            "right": "✅ He was laughed at by everyone."
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Неправильний порядок слів з by.",
            "wrong": "The child was by her aunt brought up.",
            "right": "✅ The child was brought up by her aunt."
        }
    ]
}

{
    "title": "Passive Basics",
    "items": [
        {
            "label": "Formation Rules — Правила утворення пасиву",
            "current": false
        },
        {
            "label": "Passive with Modal Verbs — Пасив з модальними",
            "current": false
        },
        {
            "label": "Causative — have/get something done",
            "current": false
        },
        {
            "label": "Get-Passive — Розмовний пасив",
            "current": false
        },
        {
            "label": "Impersonal Passive — Безособовий пасив",
            "current": false
        },
        {
            "label": "Negatives & Questions in Passive — Питання й заперечення",
            "current": false
        },
        {
            "label": "Phrasal Verbs in Passive — Фразові дієслова",
            "current": true
        },
        {
            "label": "Restrictions — Обмеження пасиву",
            "current": false
        },
        {
            "label": "Two-object Verbs in Passive — give/send/offer",
            "current": false
        },
        {
            "label": "Common Mistakes in Passive — Типові помилки",
            "current": false
        },
        {
            "label": "Formality & Style in Passive — Формальність і стиль",
            "current": false
        }
    ]
}

{
    "level": "B1–B2",
    "intro": "У цій темі ти дізнаєшся, які <strong>дієслова НЕ можуть утворювати пасив<\/strong> і чому. Це важливо, щоб уникнути граматичних помилок.",
    "rules": [
        {
            "label": "Неперехідні",
            "color": "rose",
            "text": "<strong>Неперехідні дієслова<\/strong> (без додатка) — без пасиву:",
            "example": "He arrived. ✅ (не: He was arrived. ❌)"
        },
        {
            "label": "Дієслова стану",
            "color": "amber",
            "text": "Деякі <strong>stative verbs<\/strong> — без пасиву:",
            "example": "I have a car. ✅ (не: A car is had by me. ❌)"
        },
        {
            "label": "Зворотні",
            "color": "blue",
            "text": "<strong>Зворотні дієслова<\/strong> — без пасиву:",
            "example": "She washed herself. ✅ (не: Herself was washed. ❌)"
        }
    ]
}

{
    "title": "1. Неперехідні дієслова (Intransitive Verbs)",
    "intro": "Дієслова без прямого додатка <strong>не утворюють пасиву<\/strong>:",
    "items": [
        {
            "label": "arrive",
            "title": "прибувати",
            "subtitle": "He arrived. ✅ (не: was arrived ❌)"
        },
        {
            "label": "go",
            "title": "йти",
            "subtitle": "They went home. ✅ (не: Home was gone ❌)"
        },
        {
            "label": "come",
            "title": "приходити",
            "subtitle": "She came early. ✅ (без пасиву)"
        },
        {
            "label": "sleep",
            "title": "спати",
            "subtitle": "He slept well. ✅ (без пасиву)"
        },
        {
            "label": "die",
            "title": "помирати",
            "subtitle": "The king died. ✅ (без пасиву)"
        },
        {
            "label": "happen",
            "title": "траплятися",
            "subtitle": "It happened yesterday. ✅ (без пасиву)"
        },
        {
            "label": "exist",
            "title": "існувати",
            "subtitle": "Problems exist. ✅ (без пасиву)"
        },
        {
            "label": "appear",
            "title": "з'являтися",
            "subtitle": "A ghost appeared. ✅ (без пасиву)"
        }
    ]
}

{
    "title": "2. Дієслова стану (Stative Verbs)",
    "sections": [
        {
            "label": "Володіння",
            "color": "rose",
            "description": "Дієслова <strong>володіння<\/strong> зазвичай без пасиву:",
            "examples": [
                {
                    "en": "I have a car. ✅",
                    "ua": "(не: A car is had by me. ❌)"
                },
                {
                    "en": "She owns a house. ✅",
                    "ua": "(не: A house is owned by her. ❌ — рідко)"
                },
                {
                    "en": "They possess great wealth. ✅",
                    "ua": "(не типово в пасиві)"
                }
            ]
        },
        {
            "label": "Відповідність",
            "color": "amber",
            "description": "Дієслова <strong>відповідності та схожості<\/strong>:",
            "examples": [
                {
                    "en": "The dress fits her. ✅",
                    "ua": "(не: She is fitted by the dress. ❌)"
                },
                {
                    "en": "This shirt suits you. ✅",
                    "ua": "(не: You are suited by this shirt. ❌)"
                },
                {
                    "en": "The key fits the lock. ✅",
                    "ua": "(без пасиву)"
                }
            ]
        },
        {
            "label": "Зміст \/ вміст",
            "color": "blue",
            "description": "Дієслова <strong>місткості<\/strong>:",
            "examples": [
                {
                    "en": "The hall holds 500 people. ✅",
                    "ua": "(не: 500 people are held by the hall. ❌)"
                },
                {
                    "en": "The bottle contains water. ✅",
                    "ua": "(не: Water is contained by the bottle. ❌)"
                },
                {
                    "en": "The bag weighs 5 kg. ✅",
                    "ua": "(не типово в пасиві)"
                }
            ]
        },
        {
            "label": "Взаємність",
            "color": "emerald",
            "description": "Деякі <strong>взаємні дієслова<\/strong>:",
            "examples": [
                {
                    "en": "Tom resembles his father. ✅",
                    "ua": "(не: His father is resembled by Tom. ❌)"
                },
                {
                    "en": "This equals that. ✅",
                    "ua": "(не типово в пасиві)"
                },
                {
                    "en": "They lack experience. ✅",
                    "ua": "(не: Experience is lacked. ❌)"
                }
            ]
        }
    ]
}

{
    "title": "3. Перехідні vs Неперехідні дієслова",
    "intro": "Тільки <strong>перехідні дієслова<\/strong> (з прямим додатком) утворюють пасив:",
    "rows": [
        {
            "en": "Transitive: They wrote a letter.",
            "ua": "Вони написали листа.",
            "note": "→ Passive: A letter was written. ✅"
        },
        {
            "en": "Intransitive: He arrived late.",
            "ua": "Він прибув пізно.",
            "note": "→ Passive: ❌ (немає додатка)"
        },
        {
            "en": "Transitive: She opened the door.",
            "ua": "Вона відчинила двері.",
            "note": "→ Passive: The door was opened. ✅"
        },
        {
            "en": "Intransitive: The door opened.",
            "ua": "Двері відчинилися.",
            "note": "→ Passive: ❌ (немає додатка)"
        }
    ],
    "warning": "📌 Деякі дієслова можуть бути перехідними і неперехідними залежно від контексту!"
}

{
    "title": "4. Зворотні дієслова (Reflexive Verbs)",
    "sections": [
        {
            "label": "Зворотні дії",
            "color": "rose",
            "description": "Коли суб'єкт і об'єкт <strong>однакові<\/strong>, пасив не використовується:",
            "examples": [
                {
                    "en": "She washed herself. ✅",
                    "ua": "(не: Herself was washed by her. ❌)"
                },
                {
                    "en": "He hurt himself. ✅",
                    "ua": "(не: Himself was hurt by him. ❌)"
                },
                {
                    "en": "They enjoyed themselves. ✅",
                    "ua": "(без пасиву)"
                }
            ]
        },
        {
            "label": "Взаємні дії",
            "color": "blue",
            "description": "Коли дія <strong>взаємна<\/strong> (each other):",
            "examples": [
                {
                    "en": "They love each other. ✅",
                    "ua": "(не: Each other is loved by them. ❌)"
                },
                {
                    "en": "We helped each other. ✅",
                    "ua": "(без пасиву)"
                },
                {
                    "en": "They met each other. ✅",
                    "ua": "(без пасиву)"
                }
            ]
        }
    ]
}

{
    "title": "5. Інші обмеження",
    "intro": "Деякі конструкції та значення обмежують пасив:",
    "items": [
        {
            "label": "Cognate objects",
            "title": "споріднені додатки",
            "subtitle": "live a happy life, dream a dream — без пасиву"
        },
        {
            "label": "Ідіоми",
            "title": "сталі вирази",
            "subtitle": "keep an eye on — зазвичай в активі"
        },
        {
            "label": "get + adj",
            "title": "зміна стану",
            "subtitle": "get angry, get tired — це НЕ пасив"
        },
        {
            "label": "let",
            "title": "дозволяти",
            "subtitle": "He let me go. → I was allowed to go. (не: was let)"
        }
    ]
}

{
    "title": "6. Дієслова з подвійним значенням",
    "intro": "Деякі дієслова мають перехідне і неперехідне значення:",
    "rows": [
        {
            "en": "run (transitive): They run a business.",
            "ua": "Вони ведуть бізнес.",
            "note": "→ A business is run by them. ✅"
        },
        {
            "en": "run (intransitive): He runs every day.",
            "ua": "Він бігає щодня.",
            "note": "→ ❌ (без пасиву)"
        },
        {
            "en": "grow (transitive): They grow vegetables.",
            "ua": "Вони вирощують овочі.",
            "note": "→ Vegetables are grown. ✅"
        },
        {
            "en": "grow (intransitive): Children grow fast.",
            "ua": "Діти ростуть швидко.",
            "note": "→ ❌ (без пасиву)"
        }
    ],
    "warning": "📌 Перевіряй, чи є у дієслова прямий додаток, перш ніж утворювати пасив!"
}

{
    "title": "7. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Пасив неперехідного дієслова.",
            "wrong": "The accident was happened yesterday.",
            "right": "✅ The accident happened yesterday."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Пасив дієслова володіння.",
            "wrong": "A nice house is had by her.",
            "right": "✅ She has a nice house."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Пасив зворотного дієслова.",
            "wrong": "Himself was cut by him.",
            "right": "✅ He cut himself."
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Плутання перехідного\/неперехідного.",
            "wrong": "He was arrived late.",
            "right": "✅ He arrived late."
        }
    ]
}

