}

{
    "title": "5. Прийменник \"to\" vs \"for\"",
    "sections": [
        {
            "label": "to — передача",
            "color": "emerald",
            "description": "Використовуй <strong>to<\/strong> з дієсловами передачі (give, send, tell, show, offer).",
            "examples": [
                {
                    "en": "A book was given to him.",
                    "ua": "Книгу дали йому."
                },
                {
                    "en": "The letter was sent to her.",
                    "ua": "Лист надіслали їй."
                },
                {
                    "en": "The news was told to everyone.",
                    "ua": "Новину розповіли всім."
                }
            ]
        },
        {
            "label": "for — на користь",
            "color": "blue",
            "description": "Використовуй <strong>for<\/strong> з дієсловами \"на користь\" (buy, make, cook, find, get).",
            "examples": [
                {
                    "en": "A cake was made for her.",
                    "ua": "Торт спекли для неї."
                },
                {
                    "en": "A ticket was bought for him.",
                    "ua": "Квиток купили для нього."
                },
                {
                    "en": "A solution was found for them.",
                    "ua": "Рішення знайшли для них."
                }
            ]
        }
    ]
}

